from __future__ import annotations

import json
import logging
import math
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple, Union

logger = logging.getLogger(__name__)


@dataclass
class HygieneReport:
    """Summary report generated by PreTrainingHygieneGate."""

    scanned_txt_files: int = 0
    scanned_json_files: int = 0
    modified_txt_files: int = 0
    modified_json_files: int = 0
    quarantined_files: int = 0
    total_annotations_scanned: int = 0
    valid_annotations_kept: int = 0
    removed_invalid_class_id: int = 0
    removed_corrupted_boxes: int = 0
    removed_poisoned_labels: int = 0
    errors: List[str] = field(default_factory=list)

    @property
    def total_removed(self) -> int:
        return (
            self.removed_invalid_class_id
            + self.removed_corrupted_boxes
            + self.removed_poisoned_labels
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "scanned_txt_files": self.scanned_txt_files,
            "scanned_json_files": self.scanned_json_files,
            "modified_txt_files": self.modified_txt_files,
            "modified_json_files": self.modified_json_files,
            "quarantined_files": self.quarantined_files,
            "total_annotations_scanned": self.total_annotations_scanned,
            "valid_annotations_kept": self.valid_annotations_kept,
            "removed_invalid_class_id": self.removed_invalid_class_id,
            "removed_corrupted_boxes": self.removed_corrupted_boxes,
            "removed_poisoned_labels": self.removed_poisoned_labels,
            "total_removed": self.total_removed,
            "errors": list(self.errors),
        }


class PreTrainingHygieneGate:
    """Scans and sanitizes dataset `.txt` (YOLO) and `.json` (COCO/metadata) label files
    before YOLO training begins.

    Removes:
    - Invalid class IDs (`< 0` or `> 24` by default).
    - Corrupted bounding boxes (NaN/Inf, non-positive width/height, out-of-range coordinates).
    - Poisoned labels (extreme aspect ratios, degenerate micro-boxes, full-frame spam boxes,
      duplicate overlapping poison entries, or malformed tokens).
    """

    def __init__(
        self,
        min_class_id: int = 0,
        max_class_id: int = 24,
        min_box_Side: float = 1e-4,
        max_box_area_ratio: float = 0.995,
        min_box_area_ratio: float = 1e-6,
        max_aspect_ratio: float = 100.0,
        clamp_tolerance: float = 1e-3,
        in_place: bool = True,
        remove_empty_files: bool = False,
    ) -> None:
        self.min_class_id = min_class_id
        self.max_class_id = max_class_id
        self.min_box_side = min_box_Side
        self.max_box_area_ratio = max_box_area_ratio
        self.min_box_area_ratio = min_box_area_ratio
        self.max_aspect_ratio = max_aspect_ratio
        self.clamp_tolerance = clamp_tolerance
        self.in_place = in_place
        self.remove_empty_files = remove_empty_files

    def is_valid_class_id(self, class_id: Any) -> bool:
        """Validates that class_id is an integer within [min_class_id, max_class_id]."""
        if isinstance(class_id, bool):
            return False
        if isinstance(class_id, int):
            cid = class_id
        elif isinstance(class_id, float):
            if not math.isfinite(class_id) or not class_id.is_integer():
                return False
            cid = int(class_id)
        elif isinstance(class_id, str):
            s = class_id.strip()
            if not s:
                return False
            try:
                cid = int(s)
            except ValueError:
                return False
        else:
            return False

        return self.min_class_id <= cid <= self.max_class_id

    def validate_normalized_box(
        self, cx: float, cy: float, w: float, h: float
    ) -> Tuple[bool, str, Optional[Tuple[float, float, float, float]]]:
        """Validates a normalized YOLO box (cx, cy, w, h) in [0, 1].

        Returns:
            (is_valid, reason_category, sanitized_box)
            reason_category is one of: 'ok', 'corrupted', 'poisoned'
        """
        for val in (cx, cy, w, h):
            if not isinstance(val, (int, float)) or not math.isfinite(val):
                return False, "corrupted", None

        if w <= 0.0 or h <= 0.0:
            return False, "corrupted", None

        tol = self.clamp_tolerance
        if (
            cx < -tol
            or cx > 1.0 + tol
            or cy < -tol
            or cy > 1.0 + tol
            or w > 1.0 + tol
            or h > 1.0 + tol
        ):
            return False, "corrupted", None

        # Clamp minor floating point drift within tolerance
        cx = min(max(cx, 0.0), 1.0)
        cy = min(max(cy, 0.0), 1.0)
        w = min(max(w, 0.0), 1.0)
        h = min(max(h, 0.0), 1.0)

        x1 = cx - w / 2.0
        y1 = cy - h / 2.0
        x2 = cx + w / 2.0
        y2 = cy + h / 2.0

        if x1 < -tol or y1 < -tol or x2 > 1.0 + tol or y2 > 1.0 + tol:
            return False, "corrupted", None

        # Clip box edges to [0, 1] and recompute center/size
        x1 = min(max(x1, 0.0), 1.0)
        y1 = min(max(y1, 0.0), 1.0)
        x2 = min(max(x2, 0.0), 1.0)
        y2 = min(max(y2, 0.0), 1.0)

        w = x2 - x1
        h = y2 - y1
        if w <= 0.0 or h <= 0.0:
            return False, "corrupted", None

        cx = (x1 + x2) / 2.0
        cy = (y1 + y2) / 2.0

        # Check for poisoned geometry
        area = w * h
        if w < self.min_box_side or h < self.min_box_side:
            return False, "poisoned", None
        if area < self.min_box_area_ratio or area > self.max_box_area_ratio:
            return False, "poisoned", None

        aspect = max(w / h, h / w)
        if aspect > self.max_aspect_ratio:
            return False, "poisoned", None

        return True, "ok", (cx, cy, w, h)

    def validate_polygon_coords(
        self, coords: List[float]
    ) -> Tuple[bool, str, Optional[List[float]]]:
        """Validates normalized YOLO segmentation polygon coordinates."""
        if len(coords) < 6 or len(coords) % 2 != 0:
            return False, "corrupted", None

        sanitized: List[float] = []
        xs: List[float] = []
        ys: List[float] = []
        tol = self.clamp_tolerance

        for idx, val in enumerate(coords):
            if not isinstance(val, (int, float)) or not math.isfinite(val):
                return False, "corrupted", None
            if val < -tol or val > 1.0 + tol:
                return False, "corrupted", None
            clamped = min(max(float(val), 0.0), 1.0)
            sanitized.append(clamped)
            if idx % 2 == 0:
                xs.append(clamped)
            else:
                ys.append(clamped)

        w = max(xs) - min(xs)
        h = max(ys) - min(ys)
        if w <= 0.0 or h <= 0.0:
            return False, "corrupted", None

        cx = (min(xs) + max(xs)) / 2.0
        cy = (min(ys) + max(ys)) / 2.0
        ok, reason, _ = self.validate_normalized_box(cx, cy, w, h)
        if not ok:
            return False, reason, None

        return True, "ok", sanitized

    def sanitize_txt_file(
        self, file_path: Union[str, Path], report: Optional[HygieneReport] = None
    ) -> HygieneReport:
        """Scans and cleans a single YOLO `.txt` label file."""
        if report is None:
            report = HygieneReport()

        path = Path(file_path)
        report.scanned_txt_files += 1

        try:
            raw_text = path.read_text(encoding="utf-8", errors="replace")
        except Exception as exc:
            report.errors.append(f"Failed to read {path}: {exc}")
            return report

        if "\x00" in raw_text:
            report.removed_poisoned_labels += 1
            raw_text = raw_text.replace("\x00", "")

        lines = raw_text.splitlines()
        valid_lines: List[str] = []
        seen_signatures = set()
        modified = False

        for line in lines:
            stripped = line.strip()
            if not stripped:
                continue

            report.total_annotations_scanned += 1
            parts = stripped.split()

            if len(parts) < 5:
                report.removed_corrupted_boxes += 1
                modified = True
                continue

            class_token = parts[0]
            if not self.is_valid_class_id(class_token):
                report.removed_invalid_class_id += 1
                modified = True
                continue

            cid = int(class_token)

            try:
                coords = [float(x) for x in parts[1:]]
            except ValueError:
                report.removed_poisoned_labels += 1
                modified = True
                continue

            if len(coords) == 4:
                ok, reason, box = self.validate_normalized_box(
                    coords[0], coords[1], coords[2], coords[3]
                )
                if not ok or box is None:
                    if reason == "corrupted":
                        report.removed_corrupted_boxes += 1
                    else:
                        report.removed_poisoned_labels += 1
                    modified = True
                    continue

                sig = (
                    cid,
                    round(box[0], 5),
                    round(box[1], 5),
                    round(box[2], 5),
                    round(box[3], 5),
                )
                if sig in seen_signatures:
                    report.removed_poisoned_labels += 1
                    modified = True
                    continue
                seen_signatures.add(sig)

                formatted = f"{cid} {box[0]:.6f} {box[1]:.6f} {box[2]:.6f} {box[3]:.6f}"
                if formatted != stripped:
                    modified = True
                valid_lines.append(formatted)
                report.valid_annotations_kept += 1
            else:
                ok, reason, poly = self.validate_polygon_coords(coords)
                if not ok or poly is None:
                    if reason == "corrupted":
                        report.removed_corrupted_boxes += 1
                    else:
                        report.removed_poisoned_labels += 1
                    modified = True
                    continue

                sig = (cid, tuple(round(v, 5) for v in poly))
                if sig in seen_signatures:
                    report.removed_poisoned_labels += 1
                    modified = True
                    continue
                seen_signatures.add(sig)

                coord_str = " ".join(f"{v:.6f}" for v in poly)
                formatted = f"{cid} {coord_str}"
                if formatted != stripped:
                    modified = True
                valid_lines.append(formatted)
                report.valid_annotations_kept += 1

        if modified and self.in_place:
            try:
                if not valid_lines and self.remove_empty_files:
                    path.unlink(missing_ok=True)
                    report.quarantined_files += 1
                else:
                    new_content = "\n".join(valid_lines) + ("\n" if valid_lines else "")
                    path.write_text(new_content, encoding="utf-8")
                report.modified_txt_files += 1
            except Exception as exc:
                report.errors.append(f"Failed to write sanitized {path}: {exc}")

        return report

    def _validate_pixel_or_norm_bbox(
        self,
        bbox: Any,
        img_w: Optional[float] = None,
        img_h: Optional[float] = None,
    ) -> Tuple[bool, str, Optional[List[float]]]:
        """Validates a JSON bbox `[x, y, w, h]` (either normalized or pixel space)."""
        if not isinstance(bbox, (list, tuple)) or len(bbox) != 4:
            return False, "corrupted", None

        try:
            x, y, w, h = [float(v) for v in bbox]
        except (TypeError, ValueError):
            return False, "corrupted", None

        for val in (x, y, w, h):
            if not math.isfinite(val):
                return False, "corrupted", None

        if w <= 0.0 or h <= 0.0:
            return False, "corrupted", None

        if img_w is not None and img_h is not None and img_w > 0 and img_h > 0:
            nx = (x + w / 2.0) / img_w
            ny = (y + h / 2.0) / img_h
            nw = w / img_w
            nh = h / img_h
            ok, reason, norm_box = self.validate_normalized_box(nx, ny, nw, nh)
            if not ok or norm_box is None:
                return False, reason, None
            cx, cy, sw, sh = norm_box
            clean_w = sw * img_w
            clean_h = sh * img_h
            clean_x = (cx * img_w) - clean_w / 2.0
            clean_y = (cy * img_h) - clean_h / 2.0
            return True, "ok", [clean_x, clean_y, clean_w, clean_h]

        # If dimensions unknown, detect whether normalized [0, 1] or pixel coordinates
        if max(abs(x), abs(y), w, h) <= 1.0 + self.clamp_tolerance:
            ok, reason, norm_box = self.validate_normalized_box(x, y, w, h)
            if not ok or norm_box is None:
                return False, reason, None
            return True, "ok", list(norm_box)

        # Unbounded pixel coordinates without image size metadata
        if x < 0.0 or y < 0.0 or w < 1.0 or h < 1.0:
            return False, "corrupted", None

        aspect = max(w / h, h / w)
        if aspect > self.max_aspect_ratio:
            return False, "poisoned", None

        return True, "ok", [x, y, w, h]

    def sanitize_json_file(
        self, file_path: Union[str, Path], report: Optional[HygieneReport] = None
    ) -> HygieneReport:
        """Scans and cleans a `.json` annotation file (COCO format or custom label list)."""
        if report is None:
            report = HygieneReport()

        path = Path(file_path)
        report.scanned_json_files += 1

        try:
            raw_text = path.read_text(encoding="utf-8", errors="replace")
            data = json.loads(raw_text)
        except Exception as exc:
            report.errors.append(f"Invalid JSON in {path}: {exc}")
            report.removed_poisoned_labels += 1
            return report

        modified = False

        if isinstance(data, dict):
            # Map image dimensions if COCO `images` list exists
            image_dims: Dict[Any, Tuple[float, float]] = {}
            if isinstance(data.get("images"), list):
                for img in data["images"]:
                    if isinstance(img, dict) and "id" in img:
                        iw = img.get("width")
                        ih = img.get("height")
                        if isinstance(iw, (int, float)) and isinstance(ih, (int, float)):
                            image_dims[img["id"]] = (float(iw), float(ih))

            # Clean categories if present
            if isinstance(data.get("categories"), list):
                clean_cats = []
                for cat in data["categories"]:
                    if not isinstance(cat, dict):
                        modified = True
                        continue
                    cid = cat.get("id", cat.get("category_id"))
                    if cid is not None and not self.is_valid_class_id(cid):
                        modified = True
                        continue
                    clean_cats.append(cat)
                if len(clean_cats) != len(data["categories"]):
                    data["categories"] = clean_cats
                    modified = True

            # Clean annotations list (COCO or custom `annotations` / `labels` / `objects`)
            for list_key in ("annotations", "labels", "objects", "shapes"):
                if isinstance(data.get(list_key), list):
                    clean_anns = []
                    seen_sigs = set()
                    for ann in data[list_key]:
                        report.total_annotations_scanned += 1
                        if not isinstance(ann, dict):
                            report.removed_poisoned_labels += 1
                            modified = True
                            continue

                        # Check class/category ID
                        cid = ann.get(
                            "category_id",
                            ann.get("class_id", ann.get("class", ann.get("label_id"))),
                        )
                        if cid is None or not self.is_valid_class_id(cid):
                            report.removed_invalid_class_id += 1
                            modified = True
                            continue

                        int_cid = int(cid)
                        for key_name in ("category_id", "class_id", "class", "label_id"):
                            if key_name in ann:
                                ann[key_name] = int_cid

                        # Check bounding box if present
                        if "bbox" in ann:
                            img_id = ann.get("image_id")
                            dims = image_dims.get(img_id) if img_id is not None else None
                            iw = dims[0] if dims else ann.get("image_width")
                            ih = dims[1] if dims else ann.get("image_height")
                            ok, reason, clean_bbox = self._validate_pixel_or_norm_bbox(
                                ann["bbox"], iw, ih
                            )
                            if not ok or clean_bbox is None:
                                if reason == "corrupted":
                                    report.removed_corrupted_boxes += 1
                                else:
                                    report.removed_poisoned_labels += 1
                                modified = True
                                continue
                            ann["bbox"] = clean_bbox
                            sig = (
                                ann.get("image_id"),
                                int_cid,
                                tuple(round(v, 4) for v in clean_bbox),
                            )
                            if sig in seen_sigs:
                                report.removed_poisoned_labels += 1
                                modified = True
                                continue
                            seen_sigs.add(sig)

                        clean_anns.append(ann)
                        report.valid_annotations_kept += 1

                    if len(clean_anns) != len(data[list_key]):
                        data[list_key] = clean_anns
                        modified = True

            # Single-record JSON dictionary with direct class_id / bbox fields
            if any(k in data for k in ("class_id", "category_id")) and "bbox" in data:
                report.total_annotations_scanned += 1
                cid = data.get("class_id", data.get("category_id"))
                if not self.is_valid_class_id(cid):
                    report.removed_invalid_class_id += 1
                    data["poisoned"] = True
                    modified = True
                else:
                    ok, reason, clean_bbox = self._validate_pixel_or_norm_bbox(
                        data["bbox"],
                        data.get("image_width"),
                        data.get("image_height"),
                    )
                    if not ok or clean_bbox is None:
                        if reason == "corrupted":
                            report.removed_corrupted_boxes += 1
                        else:
                            report.removed_poisoned_labels += 1
                        data["poisoned"] = True
                        modified = True
                    else:
                        data["bbox"] = clean_bbox
                        report.valid_annotations_kept += 1

        elif isinstance(data, list):
            clean_list = []
            for item in data:
                report.total_annotations_scanned += 1
                if not isinstance(item, dict):
                    report.removed_poisoned_labels += 1
                    modified = True
                    continue

                cid = item.get(
                    "category_id",
                    item.get("class_id", item.get("class", item.get("label_id"))),
                )
                if cid is None or not self.is_valid_class_id(cid):
                    report.removed_invalid_class_id += 1
                    modified = True
                    continue

                if "bbox" in item:
                    ok, reason, clean_bbox = self._validate_pixel_or_norm_bbox(
                        item["bbox"],
                        item.get("image_width"),
                        item.get("image_height"),
                    )
                    if not ok or clean_bbox is None:
                        if reason == "corrupted":
                            report.removed_corrupted_boxes += 1
                        else:
                            report.removed_poisoned_labels += 1
                        modified = True
                        continue
                    item["bbox"] = clean_bbox

                clean_list.append(item)
                report.valid_annotations_kept += 1

            if len(clean_list) != len(data):
                data = clean_list
                modified = True

        if modified and self.in_place:
            try:
                path.write_text(
                    json.dumps(data, indent=2, ensure_ascii=False) + "\n",
                    encoding="utf-8",
                )
                report.modified_json_files += 1
            except Exception as exc:
                report.errors.append(f"Failed to write sanitized JSON {path}: {exc}")

        return report

    def scan_and_clean(
        self,
        dataset_root: Union[str, Path],
        ignore_filenames: Optional[ Tuple[str, ...] ] = (
            "classes.txt",
            "README.txt",
            "requirements.txt",
            "license.txt",
        ),
    ) -> HygieneReport:
        """Recursively scans all `.txt` and `.json` files under `dataset_root`
        and cleans invalid class IDs (`<0` or `>24`), corrupted boxes, and poisoned labels.
        """
        root = Path(dataset_root)
        report = HygieneReport()

        if not root.exists():
            report.errors.append(f"Dataset root does not exist: {root}")
            return report

        ignored = {name.lower() for name in (ignore_filenames or ())}

        if root.is_file():
            if root.suffix.lower() == ".txt" and root.name.lower() not in ignored:
                self.sanitize_txt_file(root, report)
            elif root.suffix.lower() == ".json":
                self.sanitize_json_file(root, report)
            return report

        for file_path in sorted(root.rglob("*")):
            if not file_path.is_file():
                continue
            suffix = file_path.suffix.lower()
            if suffix == ".txt":
                if file_path.name.lower() in ignored:
                    continue
                self.sanitize_txt_file(file_path, report)
            elif suffix == ".json":
                self.sanitize_json_file(file_path, report)

        logger.info(
            "PreTrainingHygieneGate completed on %s: scanned=%d txt / %d json, "
            "kept=%d, removed=%d (invalid_cls=%d, corrupted_box=%d, poisoned=%d)",
            root,
            report.scanned_txt_files,
            report.scanned_json_files,
            report.valid_annotations_kept,
            report.total_removed,
            report.removed_invalid_class_id,
            report.removed_corrupted_boxes,
            report.removed_poisoned_labels,
        )
        return report
